QD({id:'dh_38',t:'Vua ban quà',c:c=>c.lv>=5,age:[35,80],th:1,w:0.5,
 x:c=>`Một viên nội thị mang đến nhà ${N(c)} chỉ dụ và quà do hoàng đế ban. Không nói vì sao, chỉ nói "bệ hạ nhớ công lao".`,
 o:c=>[{l:'Quỳ tạ, dâng sớ cảm ơn',f:c=>'Sớ cảm ơn được truyền tay các quan. Thánh ân thêm một bậc.'+fx(c,{money:m(60),fav:8,fame:4})},
  {l:'Trích một phần dâng lại cho kho công',f:c=>'Lời đồn lan: người này không tham.'+fx(c,{money:m(20),fav:5,fame:6,liem:2})}]}),
QD({id:'dh_40',t:'Môn sinh xin việc',c:c=>c.lv>=3,age:[35,75],
 x:c=>`Một học trò cũ của ${N(c)}, nay đỗ đạt mà chưa có chức, đến xin thầy giúp chạy một chân trong nha môn.`,
 o:c=>[{l:'Tiến cử với cấp trên',r:[{eq:0.6,khau:0.6},50],y:c=>'Môn sinh được nhận. Từ đó thêm một người biết ơn trong triều.'+fx(c,{fame:3,fav:1}),n:c=>'Tiến cử không thành, môn sinh hơi thất vọng.'+fx(c,{fav:-1})},
  {l:'Khuyên cứ tự thi tiếp',f:c=>'Môn sinh cúi chào, ra đi. Có thể giận, có thể hiểu.'+fx(c,{liem:2})}]}),
/* ===================== TRẠNG THÁI DÀI HẠN: TUỔI GIÀ, DI SẢN, THẤT THẾ ===================== */
DH({id:'dh_44',t:'Truyền nghề cho đời sau',head:0,age:[55,90],c:c=>!['none','huu','noi'].includes(c.job)&&c.m>=80,w:0.7,pcd:240,
 x:c=>`${N(c)} làm nghề đã mấy chục năm, tay nghề không ai trong vùng bằng. Có đứa cháu đến xin được học, mà nghề này không dạy cho ai cũng được.`,
 o:c=>[{l:'Nhận dạy tận tình',f:c=>'Đứa cháu học chăm. Có thêm người nối nghề.'+fx(c,{tam:5,fame:2,m:1})},
  {l:'Dạy một phần, giữ lại bí quyết',f:c=>'Đứa cháu học được cái cơ bản. Nghề vẫn còn bí mật.'+fx(c,{tam:2})},
  {l:'Từ chối, bảo nghề cực lắm',f:c=>'Đứa cháu đi tìm thầy khác.'+fx(c,{tam:-2})}]}),
DH({id:'dh_45',t:'Nhìn lại cuộc đời',head:0,age:[60,95],w:0.7,pcd:300,
 x:c=>`Chiều hôm ấy, ${N(c)} ngồi ngoài hiên nhìn sân. Mấy chục năm đã trôi qua như một cái chớp mắt. Người đã đi, người còn ở, những lời chưa nói.`,
 o:c=>[{l:'Viết lại vài trang hồi ký cho con cháu',f:c=>'Mấy trang giấy mỏng, nhưng con cháu giữ rất kỹ.'+fx(c,{tam:6,on:2})},
  {l:'Gọi con cháu lại, kể chuyện xưa',f:c=>'Đứa nhỏ nghe say sưa, đứa lớn nhìn nhau.'+fx(c,{tam:5,on:3})},
  {l:'Ngồi một mình thêm lát nữa',f:c=>'Gió thổi qua hiên. Lòng thấy nhẹ.'+fx(c,{tam:3})}]}),
DH({id:'dh_47',t:'Con cháu đủ đầy',age:[60,95],c:c=>clan().length>=14,w:0.6,pcd:300,
 x:c=>`Đêm ba mươi, ${N(c)} đứng giữa sân, nhìn quanh: con, cháu, chắt, dâu rể, tiếng pháo. Một nhà mà trước kia chỉ có một túp lều.`,
 o:c=>[{l:'Đặt tay lên vai từng đứa, nói lời chúc',f:c=>'Đứa nào cũng nhớ khoảnh khắc ấy rất lâu.'+fx(c,{on:5,tam:7})},
  {l:'Thắp hương tạ ơn tổ tiên',f:c=>'Khói hương lên cao. Cả nhà lặng đi một lát.'+fx(c,{on:3,cfame:1,tam:4})}]}),
DH({id:'dh_50',ms:1,t:'Bạn cũ qua đời',head:0,age:[55,95],w:0.7,pcd:200,
 x:c=>`Tin người bạn thuở nhỏ của ${N(c)} qua đời đến vào buổi sáng mưa. Hai người hơn bốn chục năm không gặp, mà tin đến vẫn đau như ngày hôm qua.`,
 o:c=>[{l:'Lên đường dự tang',f:c=>'Đường xa, nhưng đến kịp. Người nhà người bạn nắm tay không rời.'+fx(c,{tam:2,suc:-3})},
  pay('Gửi lễ vật và thư',10,{f:c=>'Thư dài một trang giấy. Nhà bạn nhận, ghi nhớ.'+fx(c,{money:-m(10),tam:-1})}),
  {l:'Thắp hương ở nhà',f:c=>'Nén hương cháy đến cuối. Lòng nặng cả tuần.'+fx(c,{tam:-3})}]}),
DH({id:'dh_56',t:'Chiếc áo cũ',head:0,age:[45,95],w:0.6,pcd:300,
 x:c=>`Dọn tủ, ${N(c)} thấy chiếc áo thô khâu vá ngày lập nghiệp: tay áo sờn, vai áo mòn. Ngần ấy năm trôi qua mà mùi nắng vẫn còn.`,
 o:c=>[{l:'Giữ lại, cất vào rương',f:c=>'Chiếc áo nằm lại đáy rương, chờ đứa cháu nào đó mở ra.'+fx(c,{tam:4})},
  {l:'Mặc thử',f:c=>'Hơi chật, nhưng lòng thấy như trẻ lại.'+fx(c,{tam:6})},
  {l:'Đem cho người nghèo',f:c=>'Chiếc áo đến tay một đứa trẻ. Nó vui như được quà.'+fx(c,{tam:2,fame:1})}]}),
DH({id:'dh_59',t:'Món nợ ba đời',age:[35,90],tier:[2,6],ms:1,w:0.5,
 x:c=>`Một ông lão tìm tới nhà ${N(c)}, xin nhắc lại món nợ: ông cố mình từng mượn của ông cố họ một thùng thóc, chưa trả. Không có giấy tờ, chỉ có lời kể truyền miệng.`,
 o:c=>[pay('Trả đủ theo giá hiện nay',40,{f:c=>'Ông lão nhận, xúc động ra về. Tiếng thơm lan khắp làng.'+fx(c,{money:-m(40),cfame:5,fame:2})}),
  pay('Trả một phần, kể rõ hoàn cảnh',15,{f:c=>'Ông lão thông cảm, nhận một nửa.'+fx(c,{money:-m(15),cfame:2})}),
  {l:'Nói không có bằng chứng',f:c=>'Ông lão buồn rầu bỏ đi. Cả xóm nghe chuyện.'+fx(c,{cfame:-4,liem:-3})}]}),
DH({id:'dh_67',t:'Quan mới chèn ép',age:[28,75],tier:[1,4],ms:1,w:0.6,
 x:c=>`Quan huyện mới đến nhậm chức, cho người sang nhà ${N(c)} "hỏi thăm", ngầm ý đòi "lễ ra mắt". Hàng xóm đã nộp, nhà mình thì chưa.`,
 o:c=>[pay('Nộp lễ vừa phải',15,{f:c=>'Quan huyện hài lòng, chuyện yên.'+fx(c,{money:-m(15)})}),
  {l:'Từ chối, nói đã nộp thuế đủ',r:[{khau:0.7,eq:0.5},45],y:c=>'Quan huyện thấy khó chịu nhưng không có cớ gì.'+fx(c,{fame:2}),n:c=>'Mấy hôm sau nhà bị thanh tra vặt vãnh.'+fx(c,{money:-m(25),tam:-3})},
  {l:'Nhờ người quen nói giúp',f:c=>'Người quen nói được một tiếng. Chuyện lắng.'+fx(c,{money:-m(5)})}]}),
DH({id:'dh_71',t:'Bán dần đồ cũ',age:[30,85],c:c=>G.money()<G.mm(30)*4,w:0.8,pcd:96,
 x:c=>`Quỹ nhà ${N(c)} cạn đến độ phải tính từng đồng. Quản gia đưa danh sách đồ có thể bán: bộ ấm trà, tấm bình phong, cặp chân nến đồng.`,
 o:c=>[{l:'Bán bình phong và ấm trà',f:c=>'Bán được một khoản nhỏ. Nhà đỡ chật mà lòng thì nặng.'+fx(c,{money:m(25),tam:-3})},
  {l:'Bán hết đồ phụ, giữ lại đồ gia truyền',f:c=>'Nhà bớt hẳn đồ đạc. Nhưng vẫn giữ được thứ cần giữ.'+fx(c,{money:m(40),tam:-4})},
  {l:'Cố cắn răng chưa bán',f:c=>'Cắt giảm bữa ăn, ai cũng thấy.'+fx(c,{tam:-2,suc:-1})}]}),
DH({id:'dh_72',t:'Cơ sở thua lỗ',age:[28,80],c:c=>S().biz.length>0,ms:1,w:0.5,
 x:c=>`Sổ cuối tháng của một cơ sở nhà ${N(c)} lỗ ba tháng liền. Người trông cơ sở nói khách bớt đi, giá nguyên liệu lại lên.`,
 o:c=>[pay('Bỏ thêm vốn chấn chỉnh',30,{r:[{tri:0.6,eq:0.4},55],y:c=>'Đổi cách làm, sang quý sau lỗ chuyển thành lãi.'+fx(c,{money:-m(30),tam:2}),n:c=>'Bỏ thêm vốn mà vẫn lỗ.'+fx(c,{money:-m(30),tam:-3})}),
  {l:'Thu hẹp, cắt bớt người',f:c=>'Cơ sở nhỏ lại, nhưng không còn lỗ.'+fx(c,{money:-m(5),tam:-1})},
  {l:'Chờ qua mùa',f:c=>'Mùa sau khá hơn một chút.'+fx(c,{money:-m(10)})}]}),
DH({id:'dh_76',t:'Cơ hội gượng dậy',age:[28,75],c:c=>G.money()<G.mm(30)*6,th:1,w:0.6,pcd:120,
 x:c=>`Một mối làm ăn nhỏ ghé qua nhà ${N(c)} đúng lúc túng thiếu: có người cần thuê gấp một đội thợ, trả công hậu. Nhà đang có người rảnh.`,
 o:c=>[{l:'Nhận làm, cử người giỏi đi',r:[{muu:0.5,eq:0.4},60],y:c=>'Công việc xong sớm. Người thuê trả đủ và hẹn lần sau.'+fx(c,{money:m(60),tam:4,fame:1}),n:c=>'Công việc chậm trễ, bị trừ công.'+fx(c,{money:m(20),tam:-1})},
  {l:'Chỉ nhận một phần nhỏ',f:c=>'Làm vừa sức, thu vừa phải.'+fx(c,{money:m(30),tam:2})}]}),
/* ===================== KỲ NGỘ ===================== */
KN({id:'kn_02',t:'Người họ xa từ nước ngoài',u:'clan',cyc:[40,80],head:1,age:[35,80],tier:[2,6],th:1,
 x:c=>`Một người lạ mang hành lý nặng đến nhà ${N(c)}, tự xưng là cháu năm đời của một nhánh họ bỏ nước ra đi từ lâu. Ông ta đã thành đạt, muốn nhận họ.`,
 o:c=>[{l:'Tiếp đón và nghe ông kể',f:c=>'Hai bên đối chiếu gia phả, quả có điểm trùng. Ông ta để lại một khoản quà và lời hẹn.'+fx(c,{money:m(100),cfame:4,on:3})},
  {l:'Mời ở lại một thời gian',f:c=>'Ông ở một tháng, chỉ dạy con cháu vài điều học được ở xứ người.'+fx(c,{money:m(60),cfame:3,tri:1,tam:4})}]}),
KN({id:'kn_03',t:'Lời tiên đoán cho cả nhà',u:'clan',cyc:[40,90],head:1,age:[35,80],
 x:c=>`Một thầy tướng đi ngang qua cổng nhà ${N(c)}, dừng bước, nhìn mái nhà, nhìn người trong nhà rồi nói đúng ba câu: một về quá khứ, một về hiện tại, một về tương lai.`,
 o:c=>[{l:'Mời vào nhà nghe thêm',r:[{tri:0.5,eq:0.5},55],y:c=>'Lời tiên đoán đúng quá nhiều chỗ khiến cả nhà để tâm, và cũng biết cách tránh một nguy cơ.'+fx(c,{cfame:3,on:3,tam:4}),n:c=>'Ông ta chỉ nói thêm những lời mơ hồ.'+fx(c,{tam:-1})},
  {l:'Cho tiền, không hỏi thêm',f:c=>'Thầy tướng cúi chào, đi tiếp.'+fx(c,{money:-m(3)})}]}),
KN({id:'kn_05',t:'Hầm rượu cổ dưới nhà',u:'clan',cyc:[40,80],head:1,age:[35,80],tier:[1,6],th:1,
 x:c=>`Thợ sửa nền nhà ${N(c)} phát hiện một hầm gạch ẩn, trong có mười chum rượu niêm kín, tuổi không dưới sáu mươi năm.`,
 o:c=>[{l:'Bán cho người sành',f:c=>'Rượu hiếm bán được giá cao. Cả vùng nghe tiếng.'+fx(c,{money:m(140),cfame:2})},
  {l:'Giữ lại để đãi khách quý',f:c=>'Mỗi dịp tiệc lớn, nhà có thêm một thứ để tự hào.'+fx(c,{cfame:3,tam:4})}]}),
KN({id:'kn_07',ms:1,t:'Danh y ghé nhà',c:c=>c.suc<60||c.cap.suc<85,age:[30,90],
 x:c=>`Một thầy thuốc nổi tiếng từ phương xa ghé xin trọ đêm tại nhà ${N(c)}. Nhìn sắc mặt chủ, ông hỏi đúng ba câu rồi gật đầu: "Bệnh ấy chữa được".`,
 o:c=>[pay('Nhờ ông kê đơn',15,{f:c=>'Thang thuốc uống ba tháng, người nhẹ hẳn.'+fx(c,{money:-m(15),suc:R(8,15),hpMax:R(1,3)})}),
  {l:'Chỉ xin vài lời dặn dò',f:c=>'Ông dặn vài điều về ăn uống, sinh hoạt. Có hiệu quả thấy rõ.'+fx(c,{suc:R(3,6),tam:2})}]}),
KN({id:'kn_08',t:'Học giả lớn ghé trọ',u:'clan',cyc:[30,70],head:1,age:[35,80],tier:[2,6],
 x:c=>`Một học giả nổi tiếng đi du ngoạn, trọ lại nhà ${N(c)} ba đêm vì trời mưa. Ông thấy giá sách của nhà, hỏi han đôi điều.`,
 o:c=>[{l:'Mời ông giảng cho con cháu',f:c=>'Ông giảng suốt ba đêm, trẻ trong nhà nghe say sưa. Tên nhà theo ông đi xa.'+fx(c,{cfame:4,tri:2,tam:3})},
  {l:'Chỉ đàm đạo với ông',f:c=>'Cuộc đàm đạo mở cho mình vài hướng nhìn mới.'+fx(c,{tri:1,fame:2})}]}),
KN({id:'kn_13',t:'Người đàn bà bí ẩn',age:[20,50],c:c=>c.g==='nam',w:0.4,
 x:c=>`Trên đường về, ${N(c)} gặp một người đàn bà mặc áo thâm, đứng bên cầu đá, hỏi bâng quơ: "Chàng có muốn nghe một chuyện không?" Giọng bà dịu mà khiến người ta không quay đi được.`,
 o:c=>[{l:'Dừng lại nghe',r:[{tri:0.5,eq:0.5},55],y:c=>'Chuyện bà kể là về một nơi, một người và một lời hứa. Về sau mình gặp lại đúng chuyện ấy.'+fx(c,{tam:4,tri:1,fame:1}),n:c=>'Chuyện nghe xong lòng thấy trống rỗng, không rõ ý.'+fx(c,{tam:-2})},
  {l:'Chắp tay rồi đi tiếp',f:c=>'Đi một đoạn quay lại, người đàn bà đã biến mất.'+fx(c,{tam:1})}]}),
KN({id:'kn_15',t:'Cây cổ thụ trong vườn',u:'clan',cyc:[40,90],head:1,age:[35,85],tier:[1,6],c:c=>farmOk(),
 x:c=>`Cơn dông làm gãy một cành của cây cổ thụ cuối vườn nhà ${N(c)}. Trong thân cây rỗng, người ta thấy một hốc lớn, trong có vài vật lạ.`,
 o:c=>[{l:'Lấy ra xem',r:[{tri:0.4,eq:0.3},60],y:c=>'Là mấy món đồ đồng cổ và một bức thư của tổ tiên.'+fx(c,{money:m(70),cfame:3,tam:4}),n:c=>'Chỉ là tổ ong và vài mảnh sành cũ.'+fx(c,{tam:-1})},
  {l:'Giữ nguyên, cho trồng lại cành',f:c=>'Cây tiếp tục sống thêm nhiều năm. Người làng nói nhà có phúc.'+fx(c,{cfame:2})}]}),
KN({id:'kn_17',t:'Mạch khoáng nhỏ trên đất nhà',u:'clan',cyc:[60,120],head:1,age:[35,85],tier:[2,6],th:1,c:c=>farmOk(),
 x:c=>`Tá điền đào mương ở góc ruộng nhà ${N(c)} thấy lớp đất đỏ lạ, có ánh kim. Thợ mỏ đi qua xem thử, nói đây là một mạch khoáng nhỏ.`,
 o:c=>[pay('Thuê thợ khai thử',30,{r:[{tri:0.5,muu:0.4},55],y:c=>'Khai được một lượng quặng đủ bán. Thu nhập thêm mấy năm.'+fx(c,{money:m(200),cfame:2}),n:c=>'Quặng nghèo, chi phí hơn thu.'+fx(c,{money:-m(30)})}),
  {l:'Bán đất khoáng cho thương nhân',f:c=>'Nhận một khoản ngay. Thương nhân hài lòng.'+fx(c,{money:m(90)})},
  {l:'Lấp lại, không để lộ',f:c=>'Chuyện được giữ kín.'+fx(c,{tam:1})}]}),
KN({id:'kn_19',t:'Lão tăng tặng kinh',age:[20,70],c:c=>c.tri>=50,w:0.4,
 x:c=>`Một lão tăng đi hóa duyên dừng chân trước cửa nhà ${N(c)}. Nhận bát cơm, ông lấy trong túi một cuốn kinh mỏng, đưa cho: "Người có tâm đọc được thì giữ".`,
 o:c=>[{l:'Nhận và đọc ngay',r:[{tri:0.7,eq:0.3},55],y:c=>'Một đoạn kinh bỗng sáng rõ như được gỡ khúc mắc lâu năm.'+fx(c,{tri:R(2,4),tam:6,eq:1}),n:c=>'Chữ nghĩa quá cao, đọc mãi không hiểu.'+fx(c,{tam:1})},
  {l:'Kính cẩn nhận, cất làm vật gia bảo',f:c=>'Cuốn kinh được đặt trên bàn thờ tổ.'+fx(c,{tam:3,cfame:1})}]}),
KN({id:'kn_21',t:'Hạt giống quý',u:'clan',cyc:[30,70],head:1,age:[30,85],c:c=>farmOk(),th:1,
 x:c=>`Một lái buôn đi qua bán cho ${N(c)} nửa túi hạt giống lạ, bảo là giống lúa chịu hạn từ phương xa. Giá không đắt, ông ta chỉ muốn "gieo duyên".`,
 o:c=>[{l:'Gieo thử một góc ruộng',r:[{tri:0.4,suc:0.2},65],y:c=>'Năm ấy hạn, góc ruộng ấy vẫn vàng. Vụ sau cả làng đến xin giống.'+fx(c,{money:m(80),cfame:3}),n:c=>'Giống không hợp đất, chết gần hết.'+fx(c,{tam:-1})},
  {l:'Cất giữ làm giống cho sau',f:c=>'Hạt giống được cất kỹ. Nhà có thêm một vốn quý.'+fx(c,{cfame:1})}]}),
KN({id:'kn_32',t:'Hang động có bí kíp',age:[18,50],c:c=>c.vo>=55,w:0.3,
 x:c=>`Trong lúc trú mưa, ${N(c)} lách vào một hang động ven núi. Đá phía trong có vết khắc: đường quyền, thế kiếm, hình người đứng tấn. Có người đã ở đây rất lâu.`,
 o:c=>[{l:'Ở lại mấy ngày chép và luyện',r:[{vo:0.7,tri:0.5},50],y:c=>'Những đường khắc trên đá nối thành một bộ công phu hoàn chỉnh.'+fx(c,{vo:R(5,10),tri:1,tam:5}),n:c=>'Luyện sai một thế, kinh mạch căng cứng nhiều ngày.'+fx(c,{suc:-R(5,10),vo:2})},
  {l:'Chép lại rồi mang về hỏi thầy',f:c=>'Thầy xem xong, chỉ ra những chỗ cần cẩn thận. Luyện chậm mà chắc.'+fx(c,{vo:R(3,6),tam:3})},
  {l:'Ra khỏi hang, không đụng gì',f:c=>'Mưa tạnh, đường dẫn xuống núi. Mình nhìn lại cửa hang một lần.'+fx(c,{tam:1})}]}),
KN({id:'kn_34',ms:1,t:'Lão ăn mày là tông sư',age:[18,55],c:c=>c.vo>=50,w:0.3,
 x:c=>`Một lão ăn mày ngồi ven đường xin tiền, thấy ${N(c)} đi qua thì cười: "Chàng đi chân ngay quá, trọng tâm hơi lệch". Lão nói trúng một khuyết điểm mình chưa ai chỉ.`,
 o:c=>[pay('Cho lão chút tiền và hỏi tiếp',3,{r:[{eq:0.7,vo:0.4},55],y:c=>'Lão chỉ vài động tác. Vài tháng sau võ công như đổi hẳn.'+fx(c,{money:-m(3),vo:R(4,8),tam:4}),n:c=>'Lão ngủ gục. Mình đứng đợi cả buổi.'+fx(c,{money:-m(3)})}),
  {l:'Cười rồi bỏ đi',f:c=>'Đi một đoạn mới thấy mình nên hỏi thêm.'+fx(c,{tam:-1})}]}),
KN({id:'kn_41',t:'Tiếng sáo dưới trăng',age:[16,60],w:0.4,
 x:c=>`Đêm trăng sáng, ${N(c)} nghe tiếng sáo từ khe núi dội xuống, trầm mà rõ. Theo tiếng, tìm đến một người ngồi trên phiến đá, mặt che nửa.`,
 o:c=>[{l:'Ngồi nghe đến hết đêm',f:c=>'Từ đó trong lòng có thêm một khúc nhạc. Hôm sau thấy nhẹ nhõm lạ.'+fx(c,{mi:R(1,3),tam:7})},
  {l:'Hỏi người ấy dạy cho vài nốt',r:[{mi:0.6,eq:0.4},50],y:c=>'Người ấy dạy cách thổi hơi. Mấy tháng sau khúc sáo của mình có chút hồn.'+fx(c,{mi:R(2,4),tam:5}),n:c=>'Người ấy lắc đầu: "Duyên chưa tới."'+fx(c,{tam:-1})}]}),
KN({id:'kn_43',t:'Thuật chữa thương cổ',job:['y','nguy'],age:[22,70],w:0.4,
 x:c=>`Một lão lang già đang hấp hối trao cho ${N(c)} cuốn sổ chữa thương bằng cây thuốc quý: "Ta không có con. Cậu có tâm thì giữ".`,
 o:c=>[{l:'Nhận sổ, hứa học đến nơi',f:c=>'Mấy tháng sau mình bốc thuốc theo sổ, hiệu nghiệm hơn trước.'+fx(c,{tri:R(1,3),m:3,fame:3})},
  {l:'Nhận sổ, chép lại cho cả hiệu thuốc',f:c=>'Cả nghề cùng hưởng lợi. Tên mình được nhớ.'+fx(c,{fame:5,cfame:2})}]}),
KN({id:'kn_57',t:'Nhà buôn nước ngoài',job:TRADE,age:[22,65],th:1,w:0.4,
 x:c=>`Một nhà buôn lạ, nói giọng nặng, tới hỏi ${N(c)} có muốn chia một chuyến hàng từ xứ ông ta mang sang. Hàng lạ, giá cao, chỉ có ít người biết.`,
 o:c=>[{l:'Nhận phần chia',r:[{tri:0.5,eq:0.5},55],y:c=>'Hàng bán sạch trong ba ngày. Lãi hơn mấy tháng thường.'+fx(c,{money:m(100),fame:2}),n:c=>'Hàng ế vì người ta chưa quen. Lỗ nhẹ.'+fx(c,{money:-m(20)})},
  {l:'Nhờ người sành kiểm hàng trước',f:c=>'Người sành chọn lọc vài món. Bán được giá vừa.'+fx(c,{money:m(50)})}]}),
KN({id:'kn_61',t:'Nhà thơ lang thang',age:[18,70],c:c=>c.tri>=50,w:0.4,
 x:c=>`Một nhà thơ gầy gò ghé quán, thấy ${N(c)} đọc sách thì mời đối thơ. Nhà thơ nổi tiếng một vùng mà mặc áo vá.`,
 o:c=>[{l:'Nhận lời đối thơ',r:[{tri:0.6,mi:0.4},50],y:c=>'Hai người đối từ chiều đến đêm. Nhà thơ tặng một câu thơ rất hay.'+fx(c,{tri:2,mi:1,fame:3,tam:6}),n:c=>'Thua đau, nhưng học được nhiều.'+fx(c,{tri:1,tam:-1})},
  {l:'Mời rượu, ngồi nghe ông đọc',f:c=>'Nghe cả đêm, say bởi thơ nhiều hơn say bởi rượu.'+fx(c,{money:-m(3),tam:6})}]}),
KN({id:'kn_66',t:'Lò gốm cổ',job:['tho','chan','mo'],age:[20,65],w:0.3,
 x:c=>`Đào nền, ${N(c)} thấy một lò gốm bỏ hoang từ rất xưa, tro nguội, men đã đóng cứng. Trên vách lò còn khắc tên người thợ cuối cùng.`,
 o:c=>[{l:'Sửa lại, nung thử',r:[{ky:0.6,tri:0.3},50],y:c=>'Mẻ gốm đầu tiên men xanh sáng như ngọc. Chợ tranh nhau mua.'+fx(c,{money:m(100),fame:4,m:3}),n:c=>'Mẻ gốm nứt vỡ. Phải học lại từ đầu.'+fx(c,{tam:-1})},
  {l:'Giữ nguyên, ghi chép lại',f:c=>'Người ta đến xem lò, mình có thêm một câu chuyện.'+fx(c,{fame:2,tri:1})}]}),
KN({id:'kn_74',t:'Đứa trẻ có tài lạ',age:[3,12],w:0.3,
 x:c=>`Không ai dạy, mà ${N(c)} vẽ được người, đếm được tiền, gọi tên từng vì sao. Hàng xóm đến xem, thấy lạ.`,
 o:c=>[{l:'Cho học thầy giỏi',f:c=>'Thầy bảo đứa trẻ này không phải loại thường.'+fx(c,{tri:R(3,6),mi:R(1,3),tam:4})},
  {l:'Để lớn tự nhiên',f:c=>'Tài năng ẩn mình, đến lúc cần mới lộ.'+fx(c,{tri:2,tam:3})}]}),
KN({id:'kn_78',ms:1,t:'Chiếc bàn cờ cổ',age:[20,80],c:c=>c.tri>=55,w:0.3,
 x:c=>`Trong một nhà bán đồ cũ, ${N(c)} thấy một bàn cờ gỗ nam, mặt cờ mòn lõm. Ông chủ nói bàn cờ ấy từng thuộc về một kỳ thủ danh tiếng.`,
 o:c=>[pay('Mua về chơi',20,{f:c=>'Đêm ấy mình bày cờ ra, thấy một thế bí từ ván cờ dở.'+fx(c,{money:-m(20),tri:R(1,3),tam:4})}),
  {l:'Chơi một ván với chủ tiệm',r:[{tri:0.8,muu:0.3},45],y:c=>'Thắng ván cờ. Ông chủ tặng lại bàn cờ như quà.'+fx(c,{tri:2,tam:6,fame:2}),n:c=>'Thua ván cờ.'+fx(c,{tam:-1})}]}),
KN({id:'kn_85',t:'Giấc mơ tiên tri',age:[18,75],w:0.4,
 x:c=>`Đêm qua ${N(c)} mơ thấy đứng trước một cánh cửa đá khắc hai chữ lạ. Sáng tỉnh, vẫn nhớ từng nét.`,
 o:c=>[{l:'Ghi lại đúng từng nét',r:[{tri:0.5,eq:0.4},50],y:c=>'Ít lâu sau mình gặp lại hai chữ ấy trong một cuốn sách cổ. Đó là điềm báo một cơ hội.'+fx(c,{tam:5,tri:1,duyen:0}),n:c=>'Nét chữ lẫn vào quên lãng.'+fx(c,{tam:-1})},
  {l:'Coi như giấc mơ thường',f:c=>'Mơ đâu thì cho qua đó.'}]}),
/* ===================== GIANG HỒ ===================== */
GH({id:'gj_02',t:'Kẻ say gây sự',age:[18,55],c:c=>c.g==='nam',w:0.7,
 x:c=>`Trong quán, một gã say vỗ bàn, chỉ mặt ${N(c)} bảo nhìn bất lịch sự. Cả quán nín thở.`,
 o:c=>[{l:'Mời gã một chén rượu',r:[{eq:0.8,khau:0.4},60],y:c=>'Gã nhận chén, cười ngượng. Cả quán thở ra.'+fx(c,{fame:1,eq:1}),n:c=>'Gã hất chén, sấn tới.'+fx(c,{tam:-2,suc:-3})},
  {l:'Đứng dậy rời quán',f:c=>'Rời đi, sau lưng tiếng cười khẩy.'+fx(c,{fame:-1})},
  {l:'Chấp nhận thử sức',r:[{vo:0.8,suc:0.3},55],y:c=>'Gã ngã sấp, rượu tỉnh. Cả quán nể.'+fx(c,{fame:4,vo:1}),n:c=>'Gã khỏe hơn nhìn, mình bị đánh đau.'+fx(c,{suc:-R(5,10),fame:-3})}]}),
GH({id:'gj_03',t:'Người đàn bà bị truy đuổi',age:[20,55],w:0.5,
 x:c=>`Một người đàn bà áo rách, mặt lấm bụi, chạy thẳng vào sân nhà ${N(c)}, quỳ xuống van xin cho trốn. Ngoài cổng đã có tiếng ngựa.`,
 o:c=>[{l:'Cho trốn vào kho',r:[{muu:0.6,eq:0.5},50],y:c=>'Toán người truy đuổi lục qua không thấy. Người đàn bà khóc tạ.'+fx(c,{fame:3,tam:3}),n:c=>'Bị lục ra. Mình bị trách cứ.'+fx(c,{fame:-3,tam:-2})},
  {l:'Từ chối, bảo là chuyện không dính',f:c=>'Người đàn bà lê bước ra cổng. Mình thấy nặng lòng.'+fx(c,{tam:-3})},
  {l:'Mời quan viên can thiệp',f:c=>'Quan cho lính dừng lại hỏi han. Cả nhà ghi nhớ.'+fx(c,{fame:1})}]}),
GH({id:'gj_05',t:'Tên ăn mày lạ',age:[16,70],w:0.6,
 x:c=>`Một tên ăn mày đến xin cơm trước cổng nhà ${N(c)}. Nhìn bàn tay hắn không phải tay người nghèo: ngón tay thon, chai ở đúng chỗ.`,
 o:c=>[{l:'Cho cơm, hỏi han',r:[{eq:0.7,tri:0.5},55],y:c=>'Hắn kể một chuyện khiến mình ngồi nghe tới tối. Hắn đi, để lại một dấu hiệu lạ.'+fx(c,{tam:3,fame:1}),n:c=>'Hắn kể chuyện bịa. Mình mất nửa buổi.'+fx(c,{tam:-1})},
  {l:'Cho cơm rồi đi',f:c=>'Hắn ăn xong, chắp tay đi.'+fx(c,{tam:1})}]}),
GH({id:'gj_10',ms:1,t:'Gánh hát giang hồ',age:[16,70],w:0.7,
 x:c=>`Một gánh hát giang hồ dựng rạp ngoài bãi. Đêm diễn kể chuyện hiệp nghĩa, người xem đứng kín. Trưởng gánh mời ${N(c)} lên xem hàng đầu.`,
 o:c=>[pay('Mua vé hàng đầu',3,{f:c=>'Xem trọn buổi, mê mẩn. Về nhà cứ nghĩ mãi một cảnh.'+fx(c,{money:-m(3),tam:5})}),
  {l:'Xem từ xa',f:c=>'Vẫn nghe rõ tiếng trống.'+fx(c,{tam:2})}]}),
GH({id:'gj_13',t:'Tin đồn bí kíp',age:[18,55],c:c=>c.vo>=40,w:0.6,
 x:c=>`Trong quán nước, người ta xì xào: bộ bí kíp của một môn phái bị mất trộm đã xuất hiện ở chợ đen. Nhiều người đang lục tìm.`,
 o:c=>[{l:'Đi dò theo tin',r:[{muu:0.6,eq:0.4},45],y:c=>'Lần ra manh mối. Dù không có bí kíp nhưng quen thêm vài người có tiếng.'+fx(c,{fame:3,eq:1}),n:c=>'Bị lừa đi một vòng, tốn tiền.'+fx(c,{money:-m(10),tam:-2})},
  {l:'Nghe cho vui',f:c=>'Chuyện qua đi như nhiều chuyện khác.'}]}),
GH({id:'gj_16',ms:1,t:'Thầy thuốc giang hồ',age:[18,70],c:c=>c.suc<70,w:0.6,
 x:c=>`Một thầy thuốc lang thang dựng quán ven đường, treo bảng "chữa thương, giải độc, mát gân cốt". Ông nhìn ${N(c)} chằm chằm, bảo mình có chỗ ứ nghẽn trong người.`,
 o:c=>[pay('Cho ông xem mạch và xoa bóp',8,{r:[{eq:0.5,tri:0.3},60],y:c=>'Một lát sau thấy nhẹ cả người.'+fx(c,{money:-m(8),suc:R(3,7),tam:3}),n:c=>'Chẳng thấy khác biệt gì.'+fx(c,{money:-m(8)})}),
  {l:'Cười, đi tiếp',f:c=>'Đi một đoạn thấy lưng hơi mỏi.'}]}),
GH({id:'gj_21',t:'Môn phái chiêu đồ',age:[12,24],c:c=>c.vo>=45||c.suc>=70,w:0.5,pcd:240,
 x:c=>{const s=sectFor(c,'chinh');return `Người của ${esc(s.n)} (chính phái, sở trường ${esc(s.st)}) đến vùng này tuyển đồ đệ. Họ để ý ${N(c)} sau khi thấy mình luyện tập.`},
 o:c=>{const s=sectFor(c,'chinh');return [
  {l:`Xin bái sư ở ${esc(s.n)}`,r:[{vo:0.6,suc:0.4,eq:0.3},50],y:c=>`${esc(s.n)} nhận làm đệ tử ngoại môn. Mấy tháng sau mình đã học được căn bản.`+fx(c,{vo:R(3,6),suc:2,fame:2,tam:4}),n:c=>'Người ta chê "chưa đủ căn cơ", bảo trở lại sau.'+fx(c,{tam:-3})},
  {l:'Từ chối, ở nhà phụ việc',f:c=>'Người ta chắp tay đi.'+fx(c,{tam:-1})}]}}),
GH({id:'gj_29',t:'Giỗ tổ sư',job:['hiep','tieu','quan_ngu'],age:[22,65],w:0.5,
 x:c=>{const s=sectFor(c,'trung');return `Đến ngày giỗ tổ của ${esc(s.n)}, người cũ trong môn phái gửi thư mời ${N(c)} về dự. Nhiều năm rồi mình chưa về.`},
 o:c=>[{l:'Về dự, mang lễ',c:()=>G.money()>=m(5),f:c=>'Gặp lại sư huynh, sư đệ cũ. Ai nấy đã già hơn. Cùng nhau uống một chén rượu thương nhớ.'+fx(c,{money:-m(5),tam:6,fame:1})},
  {l:'Gửi thư và lễ vật',f:c=>'Thư dài, lòng nặng.'+fx(c,{money:-m(3),tam:2})},
  {l:'Không về',f:c=>'Một nỗi buồn mơ hồ.'+fx(c,{tam:-3})}]}),
GH({id:'gj_44',t:'Tuyệt học sắp thất truyền',age:[25,70],c:c=>c.vo>=60&&c.tri>=50,w:0.4,
 x:c=>{const s=sectFor(c,'chinh');return `Một lão nhân tìm đến ${N(c)}, nói ông là người cuối cùng biết trọn một bộ công phu của ${esc(s.n)} thuở xưa. Ông sắp mất, mà đệ tử không còn.`},
 o:c=>[{l:'Nhận học',r:[{vo:0.7,tri:0.5},50],y:c=>'Học suốt ba tháng. Lão nhân mất, mình thành người truyền tay cuối.'+fx(c,{vo:R(4,8),tri:1,fame:4,tam:5}),n:c=>'Lão nhân mất giữa chừng, bộ công phu dang dở.'+fx(c,{vo:2,tam:-3})},
  {l:'Xin lão nhân truyền cho người khác',f:c=>'Lão nhân buồn rầu, đi tìm người khác.'+fx(c,{tam:-1})}]}),
GH({id:'gj_62',t:'Xếp hạng giang hồ',age:[22,60],c:c=>c.vo>=70&&['hiep','tieu','quan_ngu'].includes(c.job),w:0.5,pcd:300,
 x:c=>`Trong giang hồ lưu truyền một bảng xếp hạng "cao thủ", chép tay, truyền miệng. Tên ${N(c)} bất ngờ được nhắc ở một hàng gần cuối.`,
 o:c=>[{l:'Cười trừ, không bận tâm',f:c=>'Danh tiếng đến tự nhiên, đi tự nhiên.'+fx(c,{fame:3,tam:2})},
  {l:'Tìm người ở hàng trên để thử',r:[{vo:0.8,suc:0.3},40],y:c=>'Thắng. Tên mình nhích lên hàng trước.'+fx(c,{fame:8,vo:1}),n:c=>'Thua, nhưng người kia khen.'+fx(c,{fame:1,suc:-6})}]}),
GH({id:'gj_63',t:'Kẻ thù truyền đời',age:[25,65],c:c=>c.vo>=55,w:0.4,
 x:c=>{const s=sectFor(c,'ta');return `Một thanh niên của ${esc(s.n)} chặn đường ${N(c)}: "Ông của ngươi đã giết thầy của thầy ta. Hôm nay ta tới trả."`},
 o:c=>[{l:'Hỏi rõ ngọn ngành',r:[{eq:0.7,tri:0.5},50],y:c=>'Hóa ra có sự hiểu lầm, hai bên bắt tay giảng hòa.'+fx(c,{fame:3,tam:3}),n:c=>'Thanh niên không nghe, rút kiếm.'+fx(c,{suc:-5})},
  {l:'Giao đấu',r:[{vo:0.8,suc:0.3},50],y:c=>'Thanh niên thua, mà mắt vẫn đỏ. Ân oán chưa dứt.'+fx(c,{fame:5,vo:1}),n:c=>'Bị thương nặng. Thanh niên bỏ đi.'+fx(c,{suc:-R(8,16),fame:-2})},
  {l:'Tránh mặt',f:c=>'Về sau thanh niên ấy còn quay lại.'+fx(c,{tam:-2})}]}),
GH({id:'gj_64',t:'Mối thù của cha',age:[18,50],c:c=>c.vo>=50&&G.alive().some(p=>p.dead!=null&&c.parents.includes(p.id)),w:0.3,
 x:c=>{const s=sectFor(c,'ta');return `Một ông lão nói với ${N(c)}: cha mình mất năm xưa không phải do bệnh, mà do một người của ${esc(s.n)} ra tay. Ông có chứng cứ, nhưng đòi thêm thời gian để tìm thêm.`},
 o:c=>[{l:'Đi cùng ông tìm thêm chứng cứ',r:[{muu:0.6,eq:0.4},50],y:c=>'Tìm ra sự thật. Mối thù được gỡ bằng pháp luật hơn là kiếm.'+fx(c,{fame:5,tam:4}),n:c=>'Manh mối đứt. Lòng càng nặng.'+fx(c,{tam:-4})},
  {l:'Xin ông để cho yên',f:c=>'Ông lão buồn rầu, nhưng nghe.'+fx(c,{tam:-1})}]}),
GH({id:'gj_69',ms:1,t:'Cẩm y vệ truy bắt',job:['hiep'],age:[20,60],w:0.5,
 x:c=>`Người của cẩm y vệ đã đến thị trấn, hỏi về một cao thủ vừa phạm tội. Mô tả giống nhiều người, trong đó có ${N(c)}.`,
 o:c=>[{l:'Nói rõ mình không phải',r:[{khau:0.7,eq:0.5},55],y:c=>'Họ gật đầu, bỏ đi.'+fx(c,{tam:2}),n:c=>'Họ nghi ngờ, theo dõi mấy hôm.'+fx(c,{tam:-3,risk:3})},
  {l:'Rời thị trấn ngay',f:c=>'Đi nhanh nhưng bỏ lại chút việc.'+fx(c,{money:-m(5)})},
  pay('Nhờ chủ quán nói giùm',8,{f:c=>'Chủ quán nói khéo. Họ đi.'+fx(c,{money:-m(8)})})]}),
/* ===================== THẾ LỰC TỰ PHÁT ===================== */
LO({id:'lo_02',t:'Đường núi bị chặn',job:TRADE,age:[20,60],w:0.6,
 x:c=>`Một toán cầm giáo dựng rào chặn con đường núi ${N(c)} thường đi. Họ không cướp, chỉ thu "tiền qua đèo".`,
 o:c=>[{l:'Nộp tiền qua đèo',c:()=>G.money()>=m(5),f:c=>'Chúng nhận, không làm khó. Nghe nói từ nay phải nộp mỗi chuyến.'+fx(c,{money:-m(5)})},
  {l:'Thương lượng nộp theo tháng',r:[{khau:0.7,eq:0.5},50],y:c=>'Chúng đồng ý mức nhỏ hơn, cấp cho thẻ qua lại.'+fx(c,{money:-m(3),tam:1}),n:c=>'Chúng ra giá cao hơn.'+fx(c,{money:-m(10)})},
  {l:'Đi đường khác dài hơn',f:c=>'Mất thêm hai ngày nhưng khỏi nộp.'+fx(c,{money:-m(4),suc:-1})}]}),
LO({id:'lo_04',t:'Người nhà bị bắt giữ',head:1,age:[30,75],tier:[2,6],ms:1,w:0.4,
 x:c=>`Một người nhà ${N(c)} đi buôn xa, mấy hôm sau có kẻ đưa thư: người ấy bị giữ ở một trại trên núi, muốn chuộc phải mang bạc tới.`,
 o:c=>[pay('Nộp tiền chuộc',60,{f:c=>'Người nhà được thả, mệt mỏi và hoảng sợ, nhưng an toàn.'+fx(c,{money:-m(60),tam:-3})}),
  {l:'Báo quan, nhờ quân đưa quân tới',r:[{khau:0.6,eq:0.4},45],y:c=>'Quan cho lính tới. Người nhà được cứu mà không tốn tiền.'+fx(c,{fame:3,tam:1}),n:c=>'Quân đến chậm, bọn cướp đã dời. Phải nộp tiền chuộc ở nơi khác.'+fx(c,{money:-m(90),tam:-4})},
  {l:'Thuê người đi đàm phán',r:[{eq:0.6,khau:0.6},55],y:c=>'Người đàm phán giảm được nửa số tiền.'+fx(c,{money:-m(30),tam:-1}),n:c=>'Đàm phán đổ vỡ, giá chuộc cao hơn.'+fx(c,{money:-m(80),tam:-3})}]}),
LO({id:'lo_06',t:'Sơn trại mời nhập bọn',age:[18,40],c:c=>c.vo>=60&&c.g==='nam',w:0.4,
 x:c=>`Một người lạ bí mật gặp ${N(c)} ở bãi chợ, nói ngầm: trại trên núi đang cần người giỏi võ, chia phần đều, "không phải ăn nhờ ở đậu như bây giờ".`,
 o:c=>[{l:'Từ chối thẳng',f:c=>'Người ấy cúi đầu, đi. Mình thấy nhẹ lòng.'+fx(c,{liem:3})},
  {l:'Giả vờ nghe để biết nội tình',r:[{muu:0.7,eq:0.4},45],y:c=>'Biết rõ vị trí, số người. Báo cho quan, lập công.'+fx(c,{fame:6,tam:2}),n:c=>'Bị nhận ra là gián điệp, phải chạy.'+fx(c,{suc:-R(5,10),tam:-3})},
  {l:'Nhận lời',f:c=>'Chân bước vào đường tối. Ngày đầu đã thấy mình khác hẳn.'+fx(c,{liem:-8,fame:-4,tam:-2})}]}),
LO({id:'lo_10',t:'Đốt kho thóc',head:1,age:[28,75],c:c=>farmOk(),tier:[1,6],ms:1,w:0.4,
 x:c=>`Đêm nay cháy lớn ở kho thóc làng bên. Người ta bảo bọn thổ phỉ đốt để dọa dân. Có khả năng chúng sẽ đến nhà ${N(c)} tiếp theo.`,
 o:c=>[pay('Chia kho thóc thành nhiều chỗ',20,{f:c=>'Thóc chia ra, một chỗ cháy cũng không mất cả. Cả nhà thấy yên hơn.'+fx(c,{money:-m(20),tam:2})}),
  {l:'Canh kho suốt đêm',f:c=>'Thức trắng đêm, chân mỏi. Đêm yên.'+fx(c,{suc:-2,tam:1})},
  {l:'Tin rằng nhà mình không bị',f:c=>'Đêm sau kho bên cạnh bị cháy. May nhà mình thoát.'+fx(c,{tam:-1})}]}),
LO({id:'lo_11',t:'Cướp thương đội',job:TRADE,age:[20,60],w:0.5,
 x:c=>`Thương đội đi cùng ${N(c)} bị chặn ở bãi cát. Chúng đông, ngựa tốt, chỉ lấy hàng, không giết ai.`,
 o:c=>[{l:'Giao hàng, giữ mạng',f:c=>'Hàng mất, người sống.'+fx(c,{money:-m(40),tam:-3})},
  {l:'Chống cự',r:[{vo:0.7,muu:0.4},35],y:c=>'Đánh lui được. Cả đoàn khâm phục.'+fx(c,{fame:8,vo:1,money:m(10)}),n:c=>'Thua đau, mất hàng và bị thương.'+fx(c,{money:-m(40),suc:-R(8,16)})},
  {l:'Giả vờ nhượng, ngầm báo quan trạm trước',r:[{muu:0.7,eq:0.4},45],y:c=>'Quan bắt kịp bọn cướp, trả lại phần hàng.'+fx(c,{money:-m(10),fame:3}),n:c=>'Quan đến muộn.'+fx(c,{money:-m(35)})}]}),
LO({id:'lo_16',ms:1,t:'Tin dẹp xong sơn tặc',head:1,age:[28,80],w:0.5,
 x:c=>`Quan quân vừa dẹp xong trại sơn tặc ở núi phía bắc. Tiếng pháo mừng, dân làng kéo nhau ra đường. Con đường lại thông.`,
 o:c=>[pay('Góp tiền mừng chiến thắng',10,{f:c=>'Dân làng nhớ nhà ra tay. Quan huyện cũng để ý.'+fx(c,{money:-m(10),cfame:2})}),
  {l:'Vui mừng trong lòng, không làm gì',f:c=>'Đường yên, người đi lại nhiều hơn.'+fx(c,{tam:2})}]}),
LO({id:'lo_25',t:'Dân đói kéo nhau đi',head:1,age:[28,80],tier:[1,6],ms:1,w:0.5,
 x:c=>`Từ miền đói kém, một dòng người lam lũ kéo qua làng ${N(c)}, ai cũng gầy nhom. Có nhà thấy họ thì đóng cửa, có nhà mang cơm ra cổng.`,
 o:c=>[pay('Phát cháo trước cổng',20,{f:c=>'Hàng trăm người đến húp. Họ cúi đầu cảm tạ rồi đi tiếp.'+fx(c,{money:-m(20),cfame:4,fame:2})}),
  {l:'Cho nghỉ nhờ trong kho',f:c=>'Họ ở qua đêm rồi đi tiếp. Kho bẩn nhưng không ai phàn nàn.'+fx(c,{cfame:2})},
  {l:'Đóng cổng, canh gác',f:c=>'Không có chuyện xảy ra. Cũng không ai nhớ mặt mình.'+fx(c,{cfame:-2})}]}),
LO({id:'lo_36',t:'Quan đào ngũ',job:['quan'],c:c=>c.lv>=2,age:[28,70],w:0.4,
 x:c=>`Tin từ nha môn: một viên quan cùng cấp với ${N(c)} đã bỏ chức bỏ nhà, đi theo một toán nghĩa quân ở núi phía đông. Cấp trên điều tra những người từng thân với y.`,
 o:c=>[{l:'Chủ động trình báo mọi quan hệ',f:c=>'Trình báo đầy đủ, cấp trên tin tưởng.'+fx(c,{fav:4,risk:-3,liem:2})},
  {l:'Giữ im lặng',r:[{muu:0.6,eq:0.4},55],y:c=>'Không ai nhắc đến mình.'+fx(c,{tam:-1}),n:c=>'Bị gọi lên hỏi, mất uy tín.'+fx(c,{risk:6,fav:-4})},
  {l:'Tìm cách chứng minh mình không dính',f:c=>'Tốn công mà thanh thản.'+fx(c,{money:-m(8),risk:-2})}]}),
/* ===================== THẾ GIỚI ===================== */
TG({id:'tg_02',ms:1,t:'Sứ giả bị giết',head:1,age:[28,80],c:c=>!S().war,w:0.4,
 x:c=>`Tin chấn động: sứ giả của triều đình đi sứ nước láng giềng bị giết giữa đường. Chợ búa bàn tán suốt ngày. Có người nói chiến tranh sắp đến.`,
 o:c=>[pay('Tích trữ thêm lương thực',20,{f:c=>'Kho đầy thêm. Nhà yên tâm hơn.'+fx(c,{money:-m(20),tam:2})}),
  {l:'Chờ xem triều đình xử trí',f:c=>'Mọi người nín thở chờ tin.'}]}),
TG({id:'tg_03',t:'Lệnh tăng thuế quân',head:1,age:[28,80],tier:[1,6],ms:1,w:0.5,
 x:c=>`Quan huyện đọc chiếu chỉ ở đình làng: thuế quân phí năm nay tăng gấp rưỡi để lo biên ải. Dân làng nhìn nhau bàn tán.`,
 o:c=>[pay('Nộp đủ ngay',30,{f:c=>'Quan huyện ghi nhớ nhà chấp hành tốt.'+fx(c,{money:-m(30),fame:2})}),
  {l:'Xin khất nộp dần',r:[{khau:0.6,eq:0.5},55],y:c=>'Quan cho khất đến mùa gặt.'+fx(c,{money:-m(30),tam:1}),n:c=>'Quan không đồng ý, bắt nộp thêm lệ phí.'+fx(c,{money:-m(45),fame:-1})},
  {l:'Trốn thuế một phần',r:[{muu:0.6,khau:0.4},45],y:c=>'Không ai phát hiện.'+fx(c,{money:-m(12),liem:-3}),n:c=>'Bị phát hiện, phạt nặng.'+fx(c,{money:-m(80),fame:-4,liem:-4})}]}),
TG({id:'tg_11',t:'Sứ đoàn nước láng giềng qua vùng',head:1,age:[28,80],tier:[1,6],w:0.4,
 x:c=>`Sứ đoàn nước láng giềng đi qua vùng, ngựa quý, cờ xí rợp đường. Dân chúng đứng hai bên xem, trẻ con chạy theo.`,
 o:c=>[{l:'Cho con cháu ra xem',f:c=>'Bọn trẻ về kể chuyện mãi, đứa nào cũng mơ ngày được đi xa.'+fx(c,{tam:3})},
  {l:'Bán nước, lương khô ven đường',c:()=>S().biz.length>0,f:c=>'Bán được khá. Còn quen thêm vài thương nhân.'+fx(c,{money:m(20),fame:1})},
  {l:'Ở nhà',f:c=>'Một ngày như mọi ngày.'}]}),
TG({id:'tg_12',t:'Thương nhân Tây Mạc',job:TRADE,age:[20,65],th:1,w:0.5,
 x:c=>`Một đoàn thương nhân từ Tây Mạc đến, mang theo thảm, hương liệu, ngọc lạ. Họ muốn tìm người địa phương làm đầu mối bán hàng.`,
 o:c=>[{l:'Nhận làm đầu mối',r:[{eq:0.7,khau:0.5},55],y:c=>'Hàng bán chạy, hoa hồng khá. Có thêm mối quen đường xa.'+fx(c,{money:m(70),fame:2}),n:c=>'Không ai mua nổi giá cao, hoa hồng ít.'+fx(c,{money:m(10)})},
  {l:'Chỉ mua một ít về bán lẻ',f:c=>'Lời nhỏ, ít rủi ro.'+fx(c,{money:m(25)})},
  {l:'Giới thiệu người khác',f:c=>'Người kia mang quà tạ ơn.'+fx(c,{money:m(8),fame:1})}]}),
TG({id:'tg_20',t:'Giá muối lên',job:TRADE,age:[20,65],th:1,w:0.5,
 x:c=>`Giá muối ở chợ huyện lên gấp rưỡi chỉ trong mười hôm. Người ta nói nơi sản xuất bị lụt, còn người khác nói có thương nhân ém hàng.`,
 o:c=>[{l:'Tích trữ muối chờ giá cao hơn',r:[{tri:0.6,muu:0.4},50],y:c=>'Giá còn lên thêm. Bán được lời lớn.'+fx(c,{money:m(70)}),n:c=>'Giá tuột nhanh, chỉ hòa vốn.'+fx(c,{money:m(5)})},
  {l:'Bán ngay phần mình đang có',f:c=>'Lời vừa phải, yên tâm.'+fx(c,{money:m(25)})}]}),
TG({id:'tg_29',t:'Bão ở ngoài khơi',job:['ngu'],age:[18,65],w:0.5,
 x:c=>`Bầu trời ngoài khơi sẫm màu, sóng đập vào bờ khác lạ. Các lão ngư dân bảo: "Bão sắp đến". Một số thuyền vẫn nhổ neo vì bạn chài cần cá.`,
 o:c=>[{l:'Kéo thuyền lên bờ, ở nhà',f:c=>'Hai ngày sau bão ập vào, thuyền mình nguyên vẹn.'+fx(c,{tam:2})},
  {l:'Ra khơi gấp một chuyến',r:[{suc:0.6,muu:0.4},40],y:c=>'Kịp về trước bão với mẻ cá lớn.'+fx(c,{money:m(25),tam:3}),n:c=>'Bão bất ngờ đến sớm. Thuyền hỏng nặng.'+fx(c,{money:-m(40),suc:-R(8,14)})}]}),
TG({id:'tg_32',ms:1,t:'Châu chấu về',head:1,age:[28,80],c:c=>farmOk(),w:0.4,
 x:c=>`Chiều nay mây đen kéo từ phía tây, nhưng không phải mây, mà là hàng triệu con châu chấu. Dân làng đổ ra đồng gõ mõ, đốt lửa.`,
 o:c=>[{l:'Huy động cả nhà ra đồng',r:[{suc:0.5,muu:0.3},50],y:c=>'Giữ được hơn nửa ruộng. Cả nhà mệt lử.'+fx(c,{suc:-2,tam:2,cfame:1}),n:c=>'Châu chấu quá đông. Mất gần hết vụ.'+fx(c,{money:-m(30),tam:-3})},
  pay('Thuê thêm người xua đuổi',20,{f:c=>'Giữ được phần lớn ruộng nhờ thêm người.'+fx(c,{money:-m(20),tam:1})}),
  {l:'Cầu trời',f:c=>'Hôm sau gió đổi hướng, đàn châu chấu bay đi, bỏ lại ruộng tan hoang.'+fx(c,{money:-m(40),tam:-2})}]}),
TG({id:'tg_39',t:'Nạn đói lan',head:1,age:[28,80],tier:[1,6],ms:1,w:0.4,
 x:c=>`Nạn đói từ miền xa lan tới vùng này. Giá gạo gấp ba, người nghèo ăn cả vỏ cây. Quan địa phương hô hào các nhà khá giả giúp dân.`,
 o:c=>[pay('Quyên gạo cứu dân',60,{f:c=>'Hàng trăm người nhờ gạo nhà mà qua cơn đói. Tiếng nhân đức đi xa.'+fx(c,{money:-m(60),cfame:8,fame:4})}),
  pay('Góp nhỏ cùng làng',15,{f:c=>'Làng chia nhau cứu đói. Không ai bị chết đói.'+fx(c,{money:-m(15),cfame:3})}),
  {l:'Giữ gạo cho nhà',f:c=>'Nhà no đủ, nhưng ngoài cổng có tiếng người nằm than.'+fx(c,{cfame:-4,tam:-3})}]}),
/* ===================== TRIỀU ĐÌNH ===================== */
CD({id:'cd_12',t:'Cầu cạnh Đông xưởng',job:['quan'],c:c=>c.lv>=4,age:[32,70],ms:1,w:0.4,
 x:c=>`Một hoạn quan thân tín của Đông xưởng bóng gió với ${N(c)}: có thể giúp đẩy nhanh một việc, hoặc dìm một đối thủ. Nhưng "bên đó" nhớ ơn rất lâu.`,
 o:c=>[{l:'Từ chối thẳng',f:c=>'Hoạn quan cười, bảo "ngươi sẽ nhớ lời hôm nay". Từ đó có người dõi mình.'+fx(c,{risk:3,liem:4})},
  pay('Mượn tay họ chuyện nhỏ',60,{f:c=>'Việc xong gọn. Nhưng sau này trong sổ của họ có tên mình.'+fx(c,{money:-m(60),fav:5,risk:6,liem:-4})}),
  {l:'Nói để suy nghĩ',f:c=>'Hoạn quan gật. Mấy hôm sau thêm lời nhắc khẽ.'+fx(c,{risk:3})}]}),
CD({id:'cd_19',t:'Giấy gọi nhập quân hộ',head:1,age:[25,60],tier:[0,3],ms:1,w:0.4,
 x:c=>`Lý trưởng đưa tới nhà ${N(c)} tờ giấy: nhà bị xếp vào quân hộ, mỗi đời phải có một người nhập ngũ. Dân làng bảo giấy này khó cãi, nhưng cũng có cách.`,
 o:c=>[{l:'Cử một người con nhập ngũ',f:c=>'Một người trong nhà khăn gói lên đường. Cả nhà ngậm ngùi.'+fx(c,{tam:-3,on:-1})},
  pay('Nộp bạc xin chuộc',40,{f:c=>'Lý trưởng ghi nhận. Nhà khỏi phải đi, lần này.'+fx(c,{money:-m(40)})}),
  {l:'Kháng cáo lên quan huyện',r:[{khau:0.7,tri:0.5},40],y:c=>'Quan huyện xem lại sổ, thấy nhầm, xóa tên nhà khỏi quân hộ.'+fx(c,{fame:3}),n:c=>'Quan bác đơn. Mất công mất tiền.'+fx(c,{money:-m(15),tam:-2})}]}),
CD({id:'cd_34',t:'Lễ nhận sắc tước',c:c=>(c.tuoc||0)>=1,age:[30,90],ms:1,w:0.4,pcd:600,
 x:c=>`Sắc chỉ phong tước đã đến nhà ${N(c)}. Nghi lễ đòi hỏi áo mũ, hương án, sứ giả tiếp đón và một bữa tiệc ra mắt.`,
 o:c=>[pay('Làm lễ trọng thể',100,{f:c=>'Hàng trăm người tới chúc mừng. Tên nhà được nhắc khắp vùng.'+fx(c,{money:-m(100),cfame:8,fame:4})}),
  pay('Làm lễ vừa phải',30,{f:c=>'Lễ đủ phép, không phô trương. Quan khách hài lòng.'+fx(c,{money:-m(30),cfame:3})}),
  {l:'Làm lễ đơn giản, quyên số tiền còn lại cho dân nghèo',c:()=>G.money()>=m(10),f:c=>'Mọi người khen nhà biết sống.'+fx(c,{money:-m(10),cfame:5,fame:3})}]}),
CD({id:'cd_39',t:'Cha mẹ mất, phải về chịu tang',job:['quan'],c:c=>c.lv>=2&&G.age(c)>=45&&G.age(c)<=68,ms:1,w:0.4,pcd:600,
 x:c=>`Tin buồn đến muộn: người cha (hoặc mẹ) của ${N(c)} qua đời ở quê. Luật triều định quan phải rời chức về chịu tang hai mươi bảy tháng. Chỉ khi vua giữ lại mới được ở.`,
 o:c=>[{l:'Về quê chịu tang đủ hạn',f:c=>{c.busyUntil=S().t+27;return 'Mình giao việc, thu xếp đồ, về quê. Ngoài sân lễ, người làng nói: "Ông ấy không bỏ đạo hiếu".'+fx(c,{fame:5,tam:-5,liem:3})}},
  {l:'Xin vua cho đoạt tình, giữ lại chức',r:[{eq:0.6,khau:0.6},30],y:c=>'Vua chuẩn tấu. Mình ở lại kinh, lòng nặng trĩu.'+fx(c,{fav:6,fame:-3,tam:-4}),n:c=>'Triều đình bác lời xin, thêm tiếng bất hiếu.'+fx(c,{fame:-8,fav:-3})}]}),
CD({id:'cd_43',t:'Hàm quan danh dự',head:1,age:[30,80],tier:[3,6],ms:1,w:0.4,
 x:c=>`Một người trung gian nói với ${N(c)}: triều đình đang bán hàm quan danh dự cho nhà giàu có công với địa phương. Không quyền hành, nhưng có áo mũ, có tên trong sổ.`,
 o:c=>[pay('Mua một hàm',150,{f:c=>'Sắc phong nhận về. Cả vùng biết nhà có người mang hàm.'+fx(c,{money:-m(150),cfame:6,fame:-2})}),
  {l:'Từ chối, bảo công thật thì không cần mua',f:c=>'Người trung gian thở dài. Tiếng thanh liêm đến tai thanh lưu.'+fx(c,{fame:3,liem:2})}]}),
CD({id:'cd_26',t:'Vua ban thiết khoán',c:c=>c.fame>=900&&(c.tuoc||0)>=2,head:1,age:[40,90],w:0.2,pcd:900,
 x:c=>`Hoàng đế triệu ${N(c)} vào điện, ban một tấm thẻ sắt khắc chữ vàng: thiết khoán, miễn một lần tử tội cho người nhà. "Công đức nhà ngươi, trẫm nhớ."`,
 o:c=>[{l:'Quỳ nhận, dâng sớ tạ',f:c=>'Tấm thẻ sắt được đặt trên bàn thờ tổ. Cả họ biết nhà có tấm bùa hộ mệnh này.'+fx(c,{cfame:15,fame:10,tam:8})},
  {l:'Xin được từ chối, nói chưa xứng',f:c=>'Hoàng đế mỉm cười, bảo giữ giùm. Tấm thẻ vẫn đến tay trong năm sau.'+fx(c,{cfame:10,fame:8,liem:3})}]})
